  F('¿Cómo se define en C# un método asíncrono que devuelve un entero?','async Task<int> DevolverDato()',['Thread int DevolverDato()','async Thread<int> DevolverDato()','await int DevolverDato()'],'Los métodos async devuelven Task o Task<T> y se esperan con await.');
  F('Una tabla guarda NIF, nombre, apellidos, dirección y un campo «Telefonos» con dos números (916666666;917777777). ¿Qué forma normal incumple?','No cumple la 1FN: el campo teléfonos no es atómico',['Cumple la 1FN pero no la 2FN','Cumple la 2FN pero no la 3FN','Está en 3FN'],'La 1FN exige valores atómicos: un teléfono por celda (o una tabla aparte).');
  F('¿Qué consulta SQL muestra un nombre descriptivo según el valor de un campo (L → Ingreso Libre, P → Promoción Interna)?',"SELECT id, CASE forma WHEN 'L' THEN 'Ingreso Libre' WHEN 'P' THEN 'Promocion Interna' END AS f FROM proceso",["SELECT id, IF forma = 'L' THEN 'Ingreso Libre' ELSE 'Promocion Interna' ENDIF FROM proceso","SELECT id, SWITCH forma ('L' = 'Ingreso Libre') FROM proceso","SELECT id, DECODE_IF(forma,'L') FROM proceso"],'En ANSI SQL, la expresión condicional es CASE ... WHEN ... THEN ... END.');
  F('¿Qué sentencia lista los opositores con más de una solicitud?','SELECT IdOpositor, COUNT(IdSolicitud) FROM Solicitud GROUP BY IdOpositor HAVING COUNT(IdSolicitud) > 1',['SELECT IdOpositor, COUNT(IdSolicitud) FROM Solicitud WHERE COUNT(IdSolicitud) > 1 GROUP BY IdOpositor','SELECT IdOpositor FROM Solicitud WHERE COUNT(*) > 1','SELECT IdOpositor, COUNT(*) FROM Solicitud GROUP BY IdOpositor WHERE COUNT(*) > 1'],'WHERE filtra filas antes de agrupar; HAVING filtra grupos ya agrupados.');
  F('¿Qué instrucción SQL incrementa un 10 % la columna Duracion de todos los registros de Ejercicio?','UPDATE Ejercicio SET Duracion = Duracion * 1.10',['UPDATE Ejercicio SET Duracion + 10%','UPDATE TABLE Ejercicio (Duracion = Duracion + 10%)','UPDATE SET Duracion *= 1.10 FROM Ejercicio'],'UPDATE tabla SET columna = expresión.');
  F('¿Qué consulta obtiene los registros cuyo DNI (char(9)) empieza por 3?',"SELECT * FROM Opositor WHERE DNI LIKE '3%'",["SELECT * FROM Opositor WHERE DNI = 3*","SELECT * FROM Opositor WHERE DNI IN ('3.')","SELECT DNI(3*) FROM Opositor"],'% sustituye a cualquier cadena de caracteres en LIKE.');
